import { MakeLogicType, connect, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import { subscriptions } from 'kea-subscriptions'

import { teamLogic } from 'scenes/teamLogic'

import { teamSharedAgentServers } from 'products/mcp_store/frontend/gateway/agentServerUtils'
import { mcpGatewayServiceAccountsList } from 'products/mcp_store/frontend/generated/api'
import type {
    MCPServiceAccountApi,
    MCPServiceAccountServerApi,
} from 'products/mcp_store/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskConnectorsPickerLogicValues {
    currentTeamId: number | null // teamLogic
    serviceAccounts: MCPServiceAccountApi[]
    serviceAccountsFailed: boolean
    serviceAccountsLoading: boolean
    teamWorkflowServers: MCPServiceAccountServerApi[]
    workflowAccount: MCPServiceAccountApi | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskConnectorsPickerLogicActions {
    loadServiceAccounts: () => any
    loadServiceAccountsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadServiceAccountsSuccess: (
        serviceAccounts: MCPServiceAccountApi[],
        payload?: any
    ) => {
        serviceAccounts: MCPServiceAccountApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface taskConnectorsPickerLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        workflowAccount: (serviceAccounts: MCPServiceAccountApi[]) => MCPServiceAccountApi | null
        teamWorkflowServers: (workflowAccount: MCPServiceAccountApi | null) => MCPServiceAccountServerApi[]
    }
}

export type taskConnectorsPickerLogicType = MakeLogicType<
    taskConnectorsPickerLogicValues,
    taskConnectorsPickerLogicActions,
    Record<string, any>,
    taskConnectorsPickerLogicMeta
>

/** The MCP servers a workflow's "Create AI task" step can pick from: what the workflow agent reaches. */
export const taskConnectorsPickerLogic = kea<taskConnectorsPickerLogicType>([
    path(['products', 'tasks', 'frontend', 'components', 'TaskConnectorsPicker', 'taskConnectorsPickerLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        serviceAccounts: [
            [] as MCPServiceAccountApi[],
            {
                loadServiceAccounts: async (): Promise<MCPServiceAccountApi[]> => {
                    if (values.currentTeamId === null) {
                        return []
                    }
                    const response = await mcpGatewayServiceAccountsList(String(values.currentTeamId), { limit: 500 })
                    return response.results
                },
            },
        ],
    })),
    reducers({
        // Kept apart from "loaded nothing" so the empty state never shows after a failed load.
        serviceAccountsFailed: [
            false,
            {
                loadServiceAccounts: () => false,
                loadServiceAccountsFailure: () => true,
            },
        ],
    }),
    selectors({
        workflowAccount: [
            (s) => [s.serviceAccounts],
            (serviceAccounts: MCPServiceAccountApi[]): MCPServiceAccountApi | null =>
                serviceAccounts.find((account) => account.agent_key === 'workflow') ?? null,
        ],
        // Workflow runs have no credential owner, so they mount team shares only: offer exactly those.
        teamWorkflowServers: [
            (s) => [s.workflowAccount],
            (workflowAccount: MCPServiceAccountApi | null): MCPServiceAccountServerApi[] =>
                teamSharedAgentServers(workflowAccount?.servers ?? []),
        ],
    }),
    subscriptions(({ actions }) => ({
        currentTeamId: () => {
            actions.loadServiceAccounts()
        },
    })),
])
